<?php require __DIR__.'/inc/page_helpers.php';login_required();if(!page_post())go('/');check_csrf();$type=(string)($_POST['type']??'');$id=(int)($_POST['id']??0);$reason=trim((string)($_POST['reason']??''));$allowed=['user','game','item','forum_topic','forum_reply'];if(!in_array($type,$allowed,true)||$id<1||$reason===''){notice('Invalid report.','error');go('/');}$table=['user'=>'users','game'=>'games','item'=>'catalog_items','forum_topic'=>'forum_topics','forum_reply'=>'forum_replies'][$type];$q=$db->prepare("SELECT id FROM {$table} WHERE id=?");$q->execute([$id]);if(!$q->fetch()){notice('Content not found.','error');go('/');}$q=$db->prepare("SELECT COUNT(*) FROM moderation_reports WHERE reporter_id=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)");$q->execute([$currentUser['id']]);if((int)$q->fetchColumn()>=10){notice('Report limit reached. Try again later.','error');go('/');}$db->prepare('INSERT INTO moderation_reports(reporter_id,target_type,target_id,reason) VALUES(?,?,?,?)')->execute([$currentUser['id'],$type,$id,substr($reason,0,1000)]);notice('Report sent to moderators.');go('/');